import { useState } from "react";
function ContadorPasso() {
  const [contador, setContador] = useState(0);
  const [passo, setPasso] = useState(1);
  function incrementar() {
    setContador(contador + passo);
  }
  function decrementar() {
    setContador(contador - passo);
  }
  function resetar() {
    setContador(0);
  }
  return (
    <div style={{ textAlign: "center" }}>
      <h2>Contador: {contador}</h2>
      <div style={{ marginBottom: "12px" }}>
        <label>Passo: </label>
        <select value={passo} onChange={(e) => setPasso(Number(e.target.value))}>
          <option value={1}>1</option>
          <option value={5}>5</option>
          <option value={10}>10</option>
        </select>
      </div>
      <button onClick={decrementar}>-</button>
      <button onClick={incrementar} style={{ marginLeft: "8px" }}>+</button>
      <button onClick={resetar} style={{ marginLeft: "8px" }}>Resetar</button>
    </div>
  );
}
